const agentOutput = $input.first().json;
let text = agentOutput.output || agentOutput.text || agentOutput.content || '';

// Очищаем от маркдаун оберток, если ИИ их навесил
text = text.replace(/^```(?:mermaid|plantuml)?\s*\n/gm, '').replace(/\n```$/gm, '').trim();

const type = text.toLowerCase().includes('@startuml') ? 'plantuml' : 'mermaid';

if (!text) {
    return [{ json: { valid: false, error: 'Agent returned empty code.', diagram_code: '', type: type } }];
}

try {
    const response = await this.helpers.httpRequest({
        method: 'POST',
        url: 'http://kroki-kroki-1:8000/',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ diagram_source: text, diagram_type: type, output_format: 'svg' }),
        returnFullResponse: true,
        ignoreHttpStatusErrors: true
    });

    if (response.statusCode >= 400) {
        let errorMsg = 'Invalid syntax';
        const body = response.body;
        if (typeof body === 'string' && body.length > 0) {
            try { errorMsg = JSON.parse(body).message || body.substring(0, 300); } catch (e) { errorMsg = body.substring(0, 300); }
        }
        return [{ json: { valid: false, error: `Kroki Validation Error: ${errorMsg}`, diagram_code: text, type: type } }];
    }

    return [{ json: { valid: true, error: '', diagram_code: text, type: type } }];

} catch (error) {
    return [{ json: { valid: false, error: `Network Error: ${error.message}`, diagram_code: text, type: type } }];
}

// Тот же самый код валидации для второй попытки
const agentOutput = $input.first().json;
let text = agentOutput.output || agentOutput.text || agentOutput.content || '';
text = text.replace(/^```(?:mermaid|plantuml)?\s*\n/gm, '').replace(/\n```$/gm, '').trim();
const type = text.toLowerCase().includes('@startuml') ? 'plantuml' : 'mermaid';

if (!text) return [{ json: { diagram_code: '', type: type, status: 'failed' } }];

try {
    const response = await this.helpers.httpRequest({
        method: 'POST',
        url: 'http://kroki-kroki-1:8000/',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ diagram_source: text, diagram_type: type, output_format: 'svg' }),
        returnFullResponse: true,
        ignoreHttpStatusErrors: true
    });

    if (response.statusCode >= 400) {
        // Если и со второй попытки ошибка — просто возвращаем код со статусом warning
        return [{ json: { diagram_code: text, type: type, status: 'warning', message: 'Diagram may contain syntax errors' } }];
    }

    return [{ json: { diagram_code: text, type: type, status: 'success' } }];

} catch (error) {
    return [{ json: { diagram_code: text, type: type, status: 'warning', message: 'Validation service unavailable' } }];
}
